import styled from 'styled-components'
import { cores } from '../../styles'
import { Props } from '.'

export const TagContainer = styled.div<Props>`
  background-color: ${cores.rosa};
  color: ${cores.brancoSeco};
  font-size: 10px;
  font-weight: bold;
  padding: 0;

  div > div {
    display: flex;
  }
`
